-- ========================================
-- 出口报关资料（货代 xls 模板）扩展：增量升级脚本
-- 目标库：order_ai
-- 内容：报关品类 + 仓库地址库 + 渠道字典 + 模板登记，以及 skus/shipments/shipment_items 报关字段
-- 执行方式：
--   mysql -h 127.0.0.1 -uroot -p order_ai < sql/upgrade_declaration.sql
-- 说明：本脚本为一次性增量脚本（与 sql/upgrade_pi.sql 同风格），重复执行会因列已存在而报错。
-- ========================================

-- ----------------------------------------
-- 报关品类（品类表：装载报关资料上的品名/材质/海关编码/用途等申报要素）
-- ----------------------------------------
CREATE TABLE IF NOT EXISTS product_categories (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  code          VARCHAR(50)  NOT NULL DEFAULT ''  COMMENT '品类编码',
  name_en       VARCHAR(255) NOT NULL DEFAULT ''  COMMENT '产品英文品名(报关)',
  name_zh       VARCHAR(255) NOT NULL DEFAULT ''  COMMENT '产品中文品名',
  material      VARCHAR(100) NOT NULL DEFAULT ''  COMMENT '材质',
  hs_code       VARCHAR(50)  NOT NULL DEFAULT ''  COMMENT '海关编码',
  purpose       VARCHAR(100) NOT NULL DEFAULT ''  COMMENT '用途',
  brand         VARCHAR(100) NOT NULL DEFAULT '无' COMMENT '品牌',
  model         VARCHAR(100) NOT NULL DEFAULT '无' COMMENT '型号',
  product_url   VARCHAR(500) NOT NULL DEFAULT ''  COMMENT '产品链接',
  declare_price DECIMAL(15,4) NOT NULL DEFAULT 0   COMMENT '默认申报单价',
  image         VARCHAR(500) NOT NULL DEFAULT ''  COMMENT '默认图片',
  remark        VARCHAR(500) NOT NULL DEFAULT '',
  status        VARCHAR(20)  NOT NULL DEFAULT 'active',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_pc_code (code),
  KEY idx_pc_name_zh (name_zh)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报关品类(申报要素主数据)';

-- ----------------------------------------
-- 仓库地址库（FBA 仓库地址，按地址库编码带出收件人）
-- ----------------------------------------
CREATE TABLE IF NOT EXISTS warehouse_addresses (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  short_name    VARCHAR(100) NOT NULL DEFAULT '' COMMENT '地址简称(模板下拉用)',
  code          VARCHAR(50)  NOT NULL DEFAULT '' COMMENT '地址编码',
  fba_code      VARCHAR(50)  NOT NULL DEFAULT '' COMMENT 'FBA仓库代码',
  contact       VARCHAR(100) NOT NULL DEFAULT '',
  company       VARCHAR(200) NOT NULL DEFAULT '',
  tel           VARCHAR(50)  NOT NULL DEFAULT '',
  mobile        VARCHAR(50)  NOT NULL DEFAULT '',
  address1      VARCHAR(300) NOT NULL DEFAULT '',
  address2      VARCHAR(300) NOT NULL DEFAULT '',
  address3      VARCHAR(300) NOT NULL DEFAULT '',
  city          VARCHAR(100) NOT NULL DEFAULT '',
  state         VARCHAR(100) NOT NULL DEFAULT '',
  country       VARCHAR(50)  NOT NULL DEFAULT '',
  zip           VARCHAR(30)  NOT NULL DEFAULT '',
  declare_extra TEXT COMMENT '报关附注多行文本(如 Anmelder:/Declarant: 整段)',
  vat_no        VARCHAR(50)  NOT NULL DEFAULT '' COMMENT 'VAT/EORI',
  status        VARCHAR(20)  NOT NULL DEFAULT 'active',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_wa_short_name (short_name),
  KEY idx_wa_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='仓库地址库(FBA)';

-- ----------------------------------------
-- 渠道字典（货代渠道名，与 shipments.shipping_method 对齐）
-- ----------------------------------------
CREATE TABLE IF NOT EXISTS shipping_channels (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name        VARCHAR(100) NOT NULL DEFAULT '',
  country     VARCHAR(20)  NOT NULL DEFAULT '' COMMENT 'DE/UK/US...',
  sort_order  INT NOT NULL DEFAULT 0,
  status      VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_sc_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='货代渠道字典';

-- ----------------------------------------
-- 报关模板登记（含单元格映射 JSON，新增模板无需改代码）
-- ----------------------------------------
CREATE TABLE IF NOT EXISTS declaration_templates (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name        VARCHAR(100) NOT NULL DEFAULT '',
  country     VARCHAR(20)  NOT NULL DEFAULT '' COMMENT 'DE/UK...',
  carrier     VARCHAR(50)  NOT NULL DEFAULT '' COMMENT '海运/空运/卡派',
  ship_type   VARCHAR(30)  NOT NULL DEFAULT '',
  file_path   VARCHAR(300) NOT NULL DEFAULT '' COMMENT 'excel/templates/xxx.xlsx',
  source_file VARCHAR(300) NOT NULL DEFAULT '' COMMENT '原始上传 .xls',
  mapping     JSON NULL COMMENT '抬头单元格 + 明细列映射',
  remark      VARCHAR(300) NOT NULL DEFAULT '',
  status      VARCHAR(20)  NOT NULL DEFAULT 'active',
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_dt_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报关资料模板';

-- ----------------------------------------
-- 报关附加字段
-- ----------------------------------------
ALTER TABLE skus
    ADD COLUMN product_category_id BIGINT UNSIGNED NOT NULL DEFAULT 0
        COMMENT '报关品类(→product_categories.id)' AFTER category,
    ADD KEY idx_sku_product_category (product_category_id);

ALTER TABLE shipments
    ADD COLUMN warehouse_code VARCHAR(50) NOT NULL DEFAULT ''
        COMMENT '地址库编码(→warehouse_addresses.short_name)' AFTER tracking_no,
    ADD COLUMN po_number VARCHAR(200) NOT NULL DEFAULT '' AFTER warehouse_code,
    ADD COLUMN customs_mode VARCHAR(50) NOT NULL DEFAULT ''
        COMMENT '报关方式(买单报关/报关退税)' AFTER po_number,
    ADD COLUMN tax_mode VARCHAR(50) NOT NULL DEFAULT ''
        COMMENT '交税方式(包税/不包税/自主税号/自税递延)' AFTER customs_mode,
    ADD COLUMN declare_currency VARCHAR(20) NOT NULL DEFAULT 'USD'
        COMMENT '申报币种' AFTER tax_mode,
    ADD COLUMN is_electric TINYINT NOT NULL DEFAULT 0 COMMENT '带电' AFTER declare_currency,
    ADD COLUMN is_magnetic TINYINT NOT NULL DEFAULT 0 COMMENT '带磁' AFTER is_electric,
    ADD COLUMN is_liquid TINYINT NOT NULL DEFAULT 0 COMMENT '液体' AFTER is_magnetic,
    ADD COLUMN is_powder TINYINT NOT NULL DEFAULT 0 COMMENT '粉末' AFTER is_liquid,
    ADD COLUMN is_danger TINYINT NOT NULL DEFAULT 0 COMMENT '危险品' AFTER is_powder,
    ADD COLUMN need_insurance TINYINT NOT NULL DEFAULT 0 COMMENT '购买保险' AFTER is_danger,
    ADD COLUMN template_id BIGINT UNSIGNED NOT NULL DEFAULT 0
        COMMENT '上次使用的报关模板' AFTER need_insurance;

ALTER TABLE shipment_items
    ADD COLUMN carton_no VARCHAR(500) NOT NULL DEFAULT ''
        COMMENT '货箱编号/FBA货件号,如 FBA15MHZN8KKU000001-7' AFTER carton_count,
    ADD COLUMN po_number VARCHAR(200) NOT NULL DEFAULT ''
        COMMENT 'PO Number(卡派必填)' AFTER carton_no,
    ADD COLUMN carton_weight DECIMAL(10,3) NOT NULL DEFAULT 0
        COMMENT '0=取 skus.box_weight' AFTER po_number,
    ADD COLUMN carton_length DECIMAL(10,2) NOT NULL DEFAULT 0
        COMMENT '0=取 skus.box_length' AFTER carton_weight,
    ADD COLUMN carton_width DECIMAL(10,2) NOT NULL DEFAULT 0
        COMMENT '0=取 skus.box_width' AFTER carton_length,
    ADD COLUMN carton_height DECIMAL(10,2) NOT NULL DEFAULT 0
        COMMENT '0=取 skus.box_height' AFTER carton_width;

